        self.assertEqual(report["exactOne"]["pixel"], [255, 0, 0, 255])
        self.assertEqual(report["exactOne"]["opaque"], 2)  # seed pixel + exactly one new pixel
        self.assertIn("Draw · X 10 · Y 5", report["exactOne"]["status"])
        self.assertTrue(report["line"])
        self.assertEqual(report["sizeAfterKeys"], "3")
        self.assertEqual(report["square3"], 9)
        self.assertEqual(report["cursor"], {"hidden": False, "cells": [3, 3]})
        self.assertEqual(report["flat3"], 3)
        self.assertEqual(report["blendPressed"], "blend")
        self.assertEqual(report["blended"], [128, 0, 128, 255])
        self.assertEqual(report["picked"], {"colour": "#ff0000", "tool": "draw"})
        self.assertEqual(report["pickedBackground"], "#123456")
        self.assertEqual(report["rightErase"], [0, 0, 0, 0])
        self.assertEqual(report["undone"], report["rightBefore"])
        self.assertEqual(report["redone"], [0, 0, 0, 0])
        self.assertEqual(report["yRedo"], [0, 0, 0, 0])
        self.assertEqual(report["erasedSeed"], [0, 0, 0, 0])
        self.assertTrue(report["movedSame"], report)
        self.assertEqual(report["moved"]["offsets"], [3, 2], report)
        self.assertFalse(report["menu"]["hidden"])
        self.assertEqual(report["menu"]["actions"], ["grid", "fill", "clear", "reset"])
        self.assertIn("B Blend", report["menu"]["help"])
        self.assertEqual(report["grid"], "true")
        # Fill paints what the layer can show: moved by (3, 2), 61 x 30 bitmap cells land on the display.
        self.assertEqual(report["filled"], 61 * 30)
        self.assertEqual(report["cleared"], 0)
        self.assertEqual(report["unclear"], 61 * 30)
        self.assertEqual(report["reset"], initial_bitmap)
        self.assertEqual(report["confirms"], 3)
        self.assertEqual(report["textSelected"], {"toolbar": False, "painting": False})
        self.assertEqual(report["reselected"], {"toolbar": True, "tool": "move", "undo": False})
        self.assertTrue(report["narrow"]["min"], report["narrow"])
        self.assertLessEqual(report["narrow"]["overflow"], 1, report["narrow"])
        self.assertLessEqual(report["narrow"]["barRight"], report["narrow"]["viewport"] + 1, report["narrow"])

